export default async function parse_trigger({ event }: { event: { payload?: { orderId?: string; total?: number } } }) {
  const payload = event.payload
  if (!payload?.orderId) throw new Error('orderId is required')
  return { orderId: payload.orderId, total: Number(payload.total ?? 0) }
}

export default async function charge({ env, inputs }: { env: Env; inputs: Record<string, unknown> }) {
  const trigger = inputs.parse_trigger as { orderId: string; total: number }
  const response = await fetch('https://api.example.com/charges', {
    method: 'POST',
    headers: { Authorization: `Bearer ${env.CHARGE_TOKEN}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ orderId: trigger.orderId, amount: trigger.total }),
  })
  if (!response.ok) throw new Error(`Charge failed: ${response.status}`)
  return { charged: true, chargeId: (await response.json()).id }
}

export default async function skip() {
  return { charged: false }
}

export default async function notify({ env, inputs }: { env: Env; inputs: Record<string, unknown> }) {
  const trigger = inputs.parse_trigger as { orderId: string }
  const response = await fetch('https://api.example.com/confirmations', {
    method: 'POST',
    headers: { Authorization: `Bearer ${env.NOTIFY_TOKEN}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ orderId: trigger.orderId, status: 'confirmed' }),
  })
  if (!response.ok) throw new Error(`Confirmation failed: ${response.status}`)
  return { confirmed: true }
}
